example.code:

//帳票クリエータのインスタンスを生成します
CnDocCreator creator = new CnDocCreator();
//設定ファイルの読み込みます
creator.LoadConfiguration(設定ファイル);
//設定ファイルの内容をクリエータに反映します
creator.Initialize();
//IReportの実装クラスのコレクションを取得します
IEnumerator<Hos.CnDraw.Report.IReport> reportEnum = creator.ReportEnumerator();

//列挙子をコレクションの次の要素に進めます
//列挙子がコレクションの末尾を越えるまで繰り返します
while (reportEnum.MoveNext())
{
    //現在の要素をCnReport型として取得します
    CnReport cnReport = reportEnum.Current as CnReport;
    if (cnReport.Name.Equals(レポート名))
    {
         // 処理
    }
}
//出力を行います
creator.Output();

